package com.example.ayni.listing.model; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="listings") public class Listing{@Id private UUID id;@Column(name="owner_id")private UUID ownerId;@Column(name="community_id")private UUID communityId;@Column(name="category_id")private UUID categoryId;@Enumerated(EnumType.STRING)private Type type;private String title;private String description;private BigDecimal price;private String currency;@Column(name="image_url")private String imageUrl;@Enumerated(EnumType.STRING)private Status status;@Column(name="created_at")private Instant createdAt;@Column(name="updated_at")private Instant updatedAt;protected Listing(){}public Listing(UUID owner,UUID community,UUID category,Type type,String title,String description,BigDecimal price,String currency,String imageUrl){id=UUID.randomUUID();ownerId=owner;communityId=community;categoryId=category;this.type=type;this.title=title;this.description=description;this.price=price;this.currency=currency;this.imageUrl=imageUrl;status=Status.ACTIVE;}@PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;}@PreUpdate void updateTime(){updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getOwnerId(){return ownerId;}public UUID getCommunityId(){return communityId;}public UUID getCategoryId(){return categoryId;}public Type getType(){return type;}public String getTitle(){return title;}public String getDescription(){return description;}public BigDecimal getPrice(){return price;}public String getCurrency(){return currency;}public String getImageUrl(){return imageUrl;}public Status getStatus(){return status;}public void update(Type type,String title,String description,BigDecimal price,String currency,String imageUrl,Status status){this.type=type;this.title=title;this.description=description;this.price=price;this.currency=currency;this.imageUrl=imageUrl;this.status=status;}public void deactivate(){status=Status.DELETED;}public enum Type{PRODUCT,SERVICE}public enum Status{ACTIVE,PAUSED,SOLD_OUT,DELETED}}
